import React, { useEffect, useMemo } from 'react';

import { CanvasContext } from '../CanvasContext.js';
import { CanvasShape, CanvasDraw } from '../types/canvas-shape.js';

/**
 * Hook to attach and handle a canvas shape.
 * @param shape - Name of the shape to attach.
 * @param draw - Function to draw the shape.
 */
export function useCanvas(shape: string, draw: CanvasDraw) {
  const canvasContext = React.useContext(CanvasContext);
  const id = useMemo(() => `${shape}-${Math.random().toString(36)}`, []);

  const ref = React.useRef<CanvasShape>({
    id,
    draw,
  });

  useEffect(() => {
    ref.current.draw = (ctx, timestamp) => draw(ctx, timestamp, id);
    canvasContext.shapeRefs.set(id, ref);

    return () => {
      canvasContext.shapeRefs.delete(id);
    };
  });
}
